      <main id="main">
        <div id="hero">
          <HeroCentered {...{"title":"Стоматологическая клиника в Казани","action":{"label":"Записаться","href":"/booking#form"},"secondary":{"label":"Открыть каталог","href":"/services"},"image":{"src":"/_wizard/photos/6a929ab5-bea4-5d37-b68e-27e3f57dc4fc/1600","alt":"Первый экран — фото по теме «медицинская клиника»"}}} image={photo.one("top", {"src":"/_wizard/photos/6a929ab5-bea4-5d37-b68e-27e3f57dc4fc/1600","alt":"Первый экран — фото по теме «медицинская клиника»"})} />
        </div>
        <div id="catalog">
          <CatalogList {...{"entity":"service","title":"Услуги","empty":"В каталоге пока нет позиций","action":{"label":"Весь каталог","href":"/services"},"pageSize":6,"preview":true,"itemAction":{"label":"Записаться","path":"/booking"}}} />
        </div>
        <div id="contacts">
          <ContactsCards {...{"title":"Контакты","address":{"text":"Казань, ул. Баумана, 12"}}} />
        </div>
      </main>
      <FooterLegalFull {...{"brand":{"name":"Стоматологическая клиника в Казани","href":"/"},"legal":{"operator":"© 2026 Стоматологическая клиника в Казани","policy":{"label":"Политика обработки персональных данных","href":"/privacy"}},"contacts":[{"label":"Адрес","value":"Казань, ул. Баумана, 12"}],"columns":[{"title":"Разделы","links":[{"label":"Главная","href":"/"},{"label":"Услуги","href":"/services"},{"label":"Запись","href":"/booking"},{"label":"Личный кабинет","href":"/me"},{"label":"Источники фото","href":"/photos"}]}]}} />
    </>
  );
}

```

